import{_ as t,o,c as d,ag as i}from"./chunks/framework.CVaJrGn7.js";const h=JSON.parse('{"title":"@guideflow/vue","description":"@guideflow/vue — Vue 3 plugin and composables for GuideFlow product tours. Register GuideFlowPlugin and use useTour() / useGuideFlow() for reactive tour management.","frontmatter":{"description":"@guideflow/vue — Vue 3 plugin and composables for GuideFlow product tours. Register GuideFlowPlugin and use useTour() / useGuideFlow() for reactive tour management.","keywords":"@guideflow/vue, Vue 3 product tour, Vue onboarding composable, GuideFlow Vue plugin","head":[["link",{"rel":"canonical","href":"https://realnerdzw.github.io/GuideFlow/packages/vue"}],["meta",{"property":"og:url","content":"https://realnerdzw.github.io/GuideFlow/packages/vue"}],["meta",{"property":"og:title","content":"@guideflow/vue — GuideFlow.js"}],["meta",{"property":"og:description","content":"@guideflow/vue — Vue 3 plugin and composables for GuideFlow product tours. Register GuideFlowPlugin and use useTour() / useGuideFlow() for reactive tour management."}],["meta",{"name":"twitter:title","content":"@guideflow/vue — GuideFlow.js"}],["meta",{"name":"twitter:description","content":"@guideflow/vue — Vue 3 plugin and composables for GuideFlow product tours. Register GuideFlowPlugin and use useTour() / useGuideFlow() for reactive tour management."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Packages\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/packages/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"Vue\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/packages/vue/\\"}]}"]]},"headers":[],"relativePath":"packages/vue.md","filePath":"packages/vue.md","lastUpdated":1786207781000}'),a={name:"packages/vue.md"};function r(s,e,c,n,u,l){return o(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="guideflow-vue" tabindex="-1">@guideflow/vue <a class="header-anchor" href="#guideflow-vue" aria-label="Permalink to &quot;@guideflow/vue&quot;">​</a></h1><p><strong>Vue 3 plugin and composables for GuideFlow product tours.</strong></p><p><a href="https://www.npmjs.com/package/@guideflow/vue" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/v/@guideflow/vue.svg" alt="npm version"></a></p><p>A thin adapter over <a href="./core"><code>@guideflow/core</code></a>. It ships <strong>no Vue components</strong> — the tour UI is drawn by core&#39;s renderer, or by your own markup driven from <code>currentStep</code> / <code>currentContent</code>.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @guideflow/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @guideflow/vue</span></span></code></pre></div><h2 id="exports" tabindex="-1">Exports <a class="header-anchor" href="#exports" aria-label="Permalink to &quot;Exports&quot;">​</a></h2><p>This is the complete public surface.</p><table tabindex="0"><thead><tr><th>Export</th><th>Kind</th><th>Description</th></tr></thead><tbody><tr><td><code>GuideFlowPlugin</code></td><td>value</td><td>Vue plugin — provides one <code>GuideFlowInstance</code> app-wide and sets a typed <code>$guideflow</code></td></tr><tr><td><code>useGuideFlow()</code></td><td>value</td><td>Returns the injected instance; throws outside plugin scope</td></tr><tr><td><code>useTour(flowId?)</code></td><td>value</td><td>The full reactive control surface — see below</td></tr><tr><td><code>useHotspot(target, options?)</code></td><td>value</td><td>Beacon bound to a template ref or selector; removed on scope dispose</td></tr><tr><td><code>GUIDEFLOW_KEY</code></td><td>value</td><td><code>InjectionKey&lt;GuideFlowInstance&gt;</code> for manual provide/inject</td></tr><tr><td><code>GuideFlowPluginOptions</code></td><td>type</td><td><code>GuideFlowConfig</code> plus an optional <code>instance</code></td></tr><tr><td><code>UseTourReturn</code></td><td>type</td><td>Return type of <code>useTour()</code></td></tr><tr><td><code>UseHotspotReturn</code>, <code>HotspotTarget</code></td><td>type</td><td><code>useHotspot()</code>&#39;s return and target types</td></tr></tbody></table><h3 id="usetour-flowid" tabindex="-1">useTour(flowId?) <a class="header-anchor" href="#usetour-flowid" aria-label="Permalink to &quot;useTour(flowId?)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Group</th><th>Members</th></tr></thead><tbody><tr><td>Reactive state</td><td><code>isActive</code>, <code>isPaused</code>, <code>currentStepId</code>, <code>currentStepIndex</code>, <code>totalSteps</code>, <code>currentStep</code>, <code>currentContent</code>, <code>locale</code></td></tr><tr><td>Navigation</td><td><code>start</code>, <code>next</code>, <code>prev</code>, <code>goTo</code>, <code>send</code>, <code>stop</code>, <code>pause</code>, <code>resume</code>, <code>skip</code></td></tr><tr><td>Flows &amp; config</td><td><code>createFlow</code>, <code>listFlows</code>, <code>configure</code></td></tr><tr><td>Standalone UI</td><td><code>hotspot</code>, <code>removeHotspot</code>, <code>hints</code>, <code>showHints</code>, <code>hideHints</code></td></tr><tr><td>Subsystems</td><td><code>i18n</code>, <code>progress</code>, <code>setLocale</code>, <code>instance</code></td></tr></tbody></table><p>Every state field returns to its idle value when a tour ends. Listeners are released via <code>onScopeDispose()</code>.</p><p>The package augments Vue&#39;s <code>ComponentCustomProperties</code>, so <code>this.$guideflow</code> is typed in Options API components.</p><p>Core types are re-exported for convenience: <code>FlowDefinition</code>, <code>Step</code>, <code>StepContent</code>, <code>GuidanceContext</code>, <code>HotspotOptions</code>, <code>HintStep</code>, <code>GuideFlowConfig</code>, <code>PopoverPlacement</code>, <code>GuideFlowInstance</code>.</p><h2 id="peer-dependencies" tabindex="-1">Peer dependencies <a class="header-anchor" href="#peer-dependencies" aria-label="Permalink to &quot;Peer dependencies&quot;">​</a></h2><ul><li><code>vue</code> ^3.0.0</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://www.npmjs.com/package/@guideflow/vue" target="_blank" rel="noreferrer">npm</a></li><li><a href="https://github.com/RealNerdZW/GuideFlow/tree/master/packages/vue" target="_blank" rel="noreferrer">Source</a></li><li><a href="/GuideFlow/guide/vue">Vue guide</a></li><li><a href="/GuideFlow/api/vue/guide-flow-plugin">GuideFlowPlugin API</a></li><li><a href="/GuideFlow/api/vue/use-tour">useTour() API</a></li></ul>',18)])])}const g=t(a,[["render",r]]);export{h as __pageData,g as default};
